package dustin.cex.domains.security;

import dustin.cex.domains.auth.model.entity.*;
import dustin.cex.domains.auth.repository.UserRepository;
import java.nio.charset.StandardCharsets;
import java.security.*;
import java.sql.Timestamp;
import java.time.Instant;
import java.util.*;
import java.util.function.Supplier;
import org.springframework.context.annotation.DependsOn;
import org.springframework.http.HttpStatus;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.*;
import org.springframework.transaction.support.*;
import org.springframework.web.server.ResponseStatusException;
import tools.jackson.databind.ObjectMapper;

/** 개인정보 파기 보류와 해제를 서로 다른 현재 인물의 열람·내용 결합 서명으로 확정한다. */
@Service
@DependsOn("dataRetentionSchemaInitializer")
public class DataRetentionService {
    public static final String POLICY="DATA_RETENTION_V1";
    public record Payload(UUID id,String action,String scopeType,String scopeId,UUID holdId,long requesterId,UUID requesterPerson,long requesterVersion,
        long checkerId,UUID checkerPerson,long checkerVersion,String reason,String authorityReference,Instant expiresAt,String policy){}
    public record Request(Payload payload,String payloadHash,String status){}
    public record Confirmation(Request request,boolean approve,OperatorMfaService.Options authentication){}
    public record Hold(UUID id,String scopeType,String scopeId,String reason,String authorityReference,Instant createdAt,Instant releasedAt){}
    private final JdbcTemplate jdbc;private final UserRepository users;private final OperatorSessionPolicy sessions;private final OperatorMfaService mfa;
    private final AuditService audit;private final ObjectMapper json;private final TransactionTemplate tx;
    public DataRetentionService(JdbcTemplate jdbc,UserRepository users,OperatorSessionPolicy sessions,OperatorMfaService mfa,AuditService audit,ObjectMapper json,PlatformTransactionManager manager){
        this.jdbc=jdbc;this.users=users;this.sessions=sessions;this.mfa=mfa;this.audit=audit;this.json=json;tx=new TransactionTemplate(manager);tx.setIsolationLevel(TransactionDefinition.ISOLATION_READ_COMMITTED);tx.setTimeout(10);
    }
    public Request propose(long actor,UUID sid,String action,String scopeType,String scopeId,UUID holdId,long checker,String reason,String authority,UUID key){return work(actor,"DATA_RETENTION_PROPOSE",()->tx.execute(status->{
        String operation=choice(action,"HOLD","RELEASE"),scope=choice(scopeType,"USER","MAIL_JOB");validId(scope,scopeId);if(reason==null||reason.isBlank()||reason.length()>300||authority==null||authority.isBlank()||authority.length()>200||key==null)throw denied(HttpStatus.BAD_REQUEST,"보존 요청이 올바르지 않습니다");
        var people=lock(actor,checker);var maker=people.get(actor);var reviewer=people.get(checker);sessions.requireFresh(maker,sid,UserRole.OPERATOR);
        if(reviewer==null||!reviewer.isAuthenticationAllowed()||reviewer.getRole()!=UserRole.APPROVER||maker.getOperatorPersonId()==null||reviewer.getOperatorPersonId()==null||actor==checker||maker.getOperatorPersonId().equals(reviewer.getOperatorPersonId()))throw denied(HttpStatus.FORBIDDEN,"서로 다른 담당자와 승인자가 필요합니다");
        var replay=jdbc.queryForList("SELECT id FROM data_retention_requests WHERE requester_id=? AND request_key=?",UUID.class,actor,key);if(!replay.isEmpty()){var old=read(replay.getFirst(),false);var p=old.payload();if(!p.action().equals(operation)||!p.scopeType().equals(scope)||!p.scopeId().equals(scopeId)||!Objects.equals(p.holdId(),holdId)||p.checkerId()!=checker||!p.reason().equals(reason)||!p.authorityReference().equals(authority))throw denied(HttpStatus.CONFLICT,"같은 요청 키의 내용이 다릅니다");return old;}
        if("HOLD".equals(operation)){if(holdId!=null)throw denied(HttpStatus.BAD_REQUEST,"새 보존 정지에는 기존 식별자를 지정하지 않습니다");requireScope(scope,scopeId);}
        else {var hold=hold(holdId,true);if(!hold.scopeType().equals(scope)||!hold.scopeId().equals(scopeId)||hold.releasedAt()!=null)throw denied(HttpStatus.CONFLICT,"해제할 활성 보존 정지가 일치하지 않습니다");}
        UUID id=UUID.randomUUID();Instant expiry=now().plusSeconds(600);var payload=new Payload(id,operation,scope,scopeId,holdId,actor,maker.getOperatorPersonId(),maker.getVersion(),checker,reviewer.getOperatorPersonId(),reviewer.getVersion(),reason,authority,expiry,POLICY);String raw=json.writeValueAsString(payload),hash=digest(raw);
        jdbc.update("INSERT INTO data_retention_requests(id,action,scope_type,scope_id,hold_id,requester_id,requester_person,requester_version,checker_id,checker_person,checker_version,request_key,reason,authority_reference,payload,payload_hash,expires_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)",id,operation,scope,scopeId,holdId,actor,maker.getOperatorPersonId(),maker.getVersion(),checker,reviewer.getOperatorPersonId(),reviewer.getVersion(),key,reason,authority,raw,hash,Timestamp.from(expiry));
        mfa.bindApproval(OperatorMfaService.ApprovalKind.DATA_RETENTION,id,actor,maker.getVersion(),hash,expiry);audit.record(actor,"DATA_RETENTION_PROPOSED","retention-request:"+id,"SUCCESS",hash);return read(id,false);
    }));}
    public Request inspect(long actor,UUID sid,UUID id){return work(actor,"DATA_RETENTION_INSPECT",()->tx.execute(status->{var request=read(id,false);assigned(actor,sid,request);var current=users.findById(actor).orElseThrow();UUID view=UUID.randomUUID();jdbc.update("INSERT INTO data_retention_request_views(id,request_id,actor_id,actor_person,actor_version,session_id,payload_hash) VALUES(?,?,?,?,?,?,?)",view,id,actor,current.getOperatorPersonId(),current.getVersion(),sid,request.payloadHash());audit.record(actor,"DATA_RETENTION_VIEWED","retention-view:"+view,"SUCCESS",request.payloadHash());return request;}));}
    public Confirmation options(long actor,UUID sid,UUID id,String hash,boolean approve){return work(actor,"DATA_RETENTION_OPTIONS",()->tx.execute(status->{var request=check(actor,sid,id,hash);return new Confirmation(request,approve,mfa.approvalOptions(actor,sid,OperatorMfaService.ApprovalKind.DATA_RETENTION,id,hash,approve));}));}
    public Request decide(long actor,UUID sid,UUID id,String hash,boolean approve,OperatorMfaService.AuthorizationProof proof){return work(actor,"DATA_RETENTION_DECIDE",()->tx.execute(status->{var request=check(actor,sid,id,hash);mfa.authorizeApproval(actor,sid,OperatorMfaService.ApprovalKind.DATA_RETENTION,id,hash,approve,proof);jdbc.update("INSERT INTO data_retention_request_decisions(request_id,approver_id,session_id,approved,payload_hash,authorization_id) VALUES(?,?,?,?,?,?)",id,actor,sid,approve,hash,proof.challengeId());if(approve){var p=request.payload();if("HOLD".equals(p.action())){requireScope(p.scopeType(),p.scopeId());jdbc.update("INSERT INTO data_retention_holds(id,request_id,scope_type,scope_id,reason,authority_reference) VALUES(?,?,?,?,?,?)",id,id,p.scopeType(),p.scopeId(),p.reason(),p.authorityReference());audit.record(actor,"DATA_RETENTION_HOLD_APPLIED","retention-hold:"+id,"SUCCESS",p.scopeType()+":"+p.scopeId());}else{var current=hold(p.holdId(),true);if(current.releasedAt()!=null||!current.scopeType().equals(p.scopeType())||!current.scopeId().equals(p.scopeId()))throw denied(HttpStatus.CONFLICT,"현재 활성 보존 정지가 요청과 다릅니다");jdbc.update("INSERT INTO data_retention_hold_releases(hold_id,request_id) VALUES(?,?)",p.holdId(),id);audit.record(actor,"DATA_RETENTION_HOLD_RELEASED","retention-hold:"+p.holdId(),"SUCCESS","REQUEST:"+id);}}audit.record(actor,"DATA_RETENTION_DECIDED","retention-request:"+id,"SUCCESS",hash);return read(id,false);}));}
    public List<Hold> holds(int page){if(page<0||page>10000)throw denied(HttpStatus.BAD_REQUEST,"잘못된 페이지입니다");return jdbc.query("SELECT h.*,r.released_at FROM data_retention_holds h LEFT JOIN data_retention_hold_releases r ON r.hold_id=h.id ORDER BY h.created_at DESC,h.id DESC LIMIT 50 OFFSET ?",(rs,n)->new Hold(rs.getObject("id",UUID.class),rs.getString("scope_type"),rs.getString("scope_id"),rs.getString("reason"),rs.getString("authority_reference"),rs.getTimestamp("created_at").toInstant(),rs.getTimestamp("released_at")==null?null:rs.getTimestamp("released_at").toInstant()),page*50);}
    private Request check(long actor,UUID sid,UUID id,String hash){var request=read(id,true);assigned(actor,sid,request);var p=request.payload();if(actor!=p.checkerId()||!"PENDING".equals(request.status())||!Objects.equals(hash,request.payloadHash())||!p.expiresAt().isAfter(now()))throw denied(HttpStatus.CONFLICT,"보존 승인 원본이 현재와 다릅니다");if(!Boolean.TRUE.equals(jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM data_retention_request_views WHERE request_id=? AND actor_id=? AND actor_person=? AND actor_version=? AND session_id=? AND payload_hash=? AND viewed_at>=clock_timestamp()-interval '5 minutes')",Boolean.class,id,actor,p.checkerPerson(),p.checkerVersion(),sid,hash)))throw denied(HttpStatus.CONFLICT,"현재 승인 내용을 먼저 열람해야 합니다");return request;}
    private void assigned(long actor,UUID sid,Request request){var p=request.payload();var people=lock(actor,p.requesterId(),p.checkerId());var current=people.get(actor);sessions.requireFresh(current,sid,UserRole.OPERATOR,UserRole.APPROVER);var maker=people.get(p.requesterId());var checker=people.get(p.checkerId());if(maker==null||checker==null||!maker.isAuthenticationAllowed()||!checker.isAuthenticationAllowed()||maker.getRole()!=UserRole.OPERATOR||checker.getRole()!=UserRole.APPROVER||maker.getVersion()!=p.requesterVersion()||checker.getVersion()!=p.checkerVersion()||!p.requesterPerson().equals(maker.getOperatorPersonId())||!p.checkerPerson().equals(checker.getOperatorPersonId())||(actor!=p.requesterId()&&actor!=p.checkerId()))throw denied(HttpStatus.FORBIDDEN,"현재 지정 인물이 아닙니다");}
    private Request read(UUID id,boolean lock){var rows=jdbc.queryForList("SELECT q.*,d.approved,(SELECT h.id FROM data_retention_holds h WHERE h.request_id=q.id) applied_hold,(SELECT r.hold_id FROM data_retention_hold_releases r WHERE r.request_id=q.id) applied_release FROM data_retention_requests q LEFT JOIN data_retention_request_decisions d ON d.request_id=q.id WHERE q.id=?"+(lock?" FOR UPDATE OF q":""),id);if(rows.size()!=1)throw denied(HttpStatus.NOT_FOUND,"보존 요청이 없습니다");var row=rows.getFirst();try{String raw=(String)row.get("payload");var payload=json.readValue(raw,Payload.class);if(!payload.id().equals(id)||!POLICY.equals(payload.policy())||!digest(raw).equals(row.get("payload_hash")))throw new IllegalStateException();String state=row.get("applied_hold")!=null||row.get("applied_release")!=null?"APPLIED":row.get("approved")==null?(payload.expiresAt().isAfter(now())?"PENDING":"EXPIRED"):(Boolean.TRUE.equals(row.get("approved"))?"APPROVED":"REJECTED");return new Request(payload,(String)row.get("payload_hash"),state);}catch(Exception invalid){throw denied(HttpStatus.SERVICE_UNAVAILABLE,"보존 요청 원본을 검증할 수 없습니다");}}
    private Hold hold(UUID id,boolean lock){if(id==null)throw denied(HttpStatus.BAD_REQUEST,"보존 정지 식별자가 필요합니다");var rows=jdbc.queryForList("SELECT h.*,r.released_at FROM data_retention_holds h LEFT JOIN data_retention_hold_releases r ON r.hold_id=h.id WHERE h.id=?"+(lock?" FOR UPDATE OF h":""),id);if(rows.size()!=1)throw denied(HttpStatus.NOT_FOUND,"보존 정지가 없습니다");var row=rows.getFirst();return new Hold(id,(String)row.get("scope_type"),(String)row.get("scope_id"),(String)row.get("reason"),(String)row.get("authority_reference"),((Timestamp)row.get("created_at")).toInstant(),row.get("released_at")==null?null:((Timestamp)row.get("released_at")).toInstant());}
    private void requireScope(String type,String id){boolean exists="USER".equals(type)?Boolean.TRUE.equals(jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM users WHERE id=?::bigint)",Boolean.class,id)):Boolean.TRUE.equals(jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM customer_mail_jobs WHERE id=?::uuid)",Boolean.class,id));if(!exists)throw denied(HttpStatus.NOT_FOUND,"보존 대상이 없습니다");}
    private static void validId(String type,String id){if(id==null||("USER".equals(type)&&!id.matches("[1-9][0-9]{0,18}"))||("MAIL_JOB".equals(type)&&!id.matches("[0-9a-fA-F-]{36}")))throw denied(HttpStatus.BAD_REQUEST,"보존 대상 식별자가 올바르지 않습니다");}
    private Map<Long,User> lock(long... ids){var result=new HashMap<Long,User>();for(long id:Arrays.stream(ids).distinct().sorted().toArray())users.lockById(id).ifPresent(user->result.put(id,user));return result;}
    private Instant now(){return jdbc.queryForObject("SELECT clock_timestamp()",Timestamp.class).toInstant();}
    private static String choice(String value,String a,String b){if(!Objects.equals(value,a)&&!Objects.equals(value,b))throw denied(HttpStatus.BAD_REQUEST,"허용하지 않는 보존 구분입니다");return value;}
    private static String digest(String value){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8)));}catch(NoSuchAlgorithmException impossible){throw new IllegalStateException(impossible);}}
    private <T>T work(long actor,String action,Supplier<T> callback){if(TransactionSynchronizationManager.isActualTransactionActive())throw new IllegalStateException("보존 통제는 독립 트랜잭션으로 실행하세요");try{return callback.get();}catch(ResponseStatusException failure){audit.denied(actor,action,"retention-restricted","POLICY_"+failure.getStatusCode().value());throw failure;}}
    private static ResponseStatusException denied(HttpStatus status,String message){return new ResponseStatusException(status,message);}
}
